import { createContext, useContext, useState, useEffect, type ReactNode } from 'react'
import type { User } from '@/entities/user/types'
import { supabaseAuthService } from '@/integrations/supabase/auth'
import { rolesService, type AppRole } from '@/integrations/supabase/roles'
import { ensureDevSuperadminSession } from '@/app/devAutoLogin'

type AuthContextValue = {
  user: User | null
  isLoading: boolean
  isAuthenticated: boolean
  roles: AppRole[]
  isAdmin: boolean
  isSuperAdmin: boolean
  signOut: () => Promise<void>
}

const AuthContext = createContext<AuthContextValue>({
  user: null,
  isLoading: true,
  isAuthenticated: false,
  roles: [],
  isAdmin: false,
  isSuperAdmin: false,
  signOut: async () => {},
})

export function useAuth() {
  return useContext(AuthContext)
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [roles, setRoles] = useState<AppRole[]>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    const loadRoles = async (u: User | null) => {
      if (!u) {
        setRoles([])
        return
      }
      const r = await rolesService.getMyRoles()
      setRoles(r)
    }

    // Register listener FIRST (sync) so we never miss events
    const { unsubscribe } = supabaseAuthService.onAuthStateChange((u) => {
      setUser(u)
      setIsLoading(false)
      // Defer Supabase calls out of the auth callback
      setTimeout(() => loadRoles(u), 0)
    })

    // Then validate the current user against the auth server.
    // In dev, auto-login as the seeded super_admin if no session exists.
    ;(async () => {
      let u = await supabaseAuthService.getUser()
      if (!u && import.meta.env.DEV) {
        await ensureDevSuperadminSession()
        u = await supabaseAuthService.getUser()
      }
      setUser(u)
      setIsLoading(false)
      loadRoles(u)
    })()

    return unsubscribe
  }, [])

  const signOut = async () => {
    await supabaseAuthService.signOut()
    setUser(null)
    setRoles([])
  }

  const isSuperAdmin = roles.includes('super_admin')
  const isAdmin = isSuperAdmin || roles.includes('tenant_admin')

  return (
    <AuthContext.Provider
      value={{
        user,
        isLoading,
        isAuthenticated: !!user,
        roles,
        isAdmin,
        isSuperAdmin,
        signOut,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}
